package credentials

import "testing"

// This audit uses synthetic key material and performs no storage or network I/O.
func BenchmarkAuditStoredCredentialDecryption(b *testing.B) {
	service, err := NewEncryptionService(make([]byte, 32))
	if err != nil {
		b.Fatal(err)
	}
	encrypted, err := service.EncryptCredential(`{"api-key":"synthetic-audit-value"}`)
	if err != nil {
		b.Fatal(err)
	}
	b.ReportAllocs()
	for b.Loop() {
		decrypted, err := service.DecryptCredential(encrypted)
		if err != nil {
			b.Fatal(err)
		}
		if decrypted != `{"api-key":"synthetic-audit-value"}` {
			b.Fatal("incorrect plaintext")
		}
	}
}
